#include <vector>
#include <unordered_map>

class Solution {
public:
    std::vector<int> numberOfPairs(std::vector<int>& nums1, std::vector<int>& nums2, std::vector<std::vector<int>>& queries) {
        std::vector<int> n2 = nums2;
        std::unordered_map<int, int> freq;
        for (int x : n2) freq[x]++;
        std::vector<int> ans;
        for (const auto& q : queries) {
            if (q[0] == 1) {
                int l = q[1], r = q[2], val = q[3];
                for (int i = l; i <= r; ++i) {
                    freq[n2[i]]--;
                    n2[i] += val;
                    freq[n2[i]]++;
                }
            } else {
                int tot = q[1];
                int totalPairs = 0;
                for (int x : nums1) {
                    int target = tot - x;
                    if (freq.count(target)) totalPairs += freq[target];
                }
                ans.push_back(totalPairs);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] numberOfPairs(int[] nums1, int[] nums2, int[][] queries) {
        int[] n2 = nums2.clone();
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : n2) freq.put(x, freq.getOrDefault(x, 0) + 1);
        List<Integer> list = new ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 1) {
                int l = q[1], r = q[2], val = q[3];
                for (int i = l; i <= r; i++) {
                    freq.put(n2[i], freq.get(n2[i]) - 1);
                    n2[i] += val;
                    freq.put(n2[i], freq.getOrDefault(n2[i], 0) + 1);
                }
            } else {
                int tot = q[1];
                int totalPairs = 0;
                for (int x : nums1) {
                    int target = tot - x;
                    totalPairs += freq.getOrDefault(target, 0);
                }
                list.add(totalPairs);
            }
        }
        int[] ans = new int[list.size()];
        for (int i = 0; i < list.size(); i++) ans[i] = list.get(i);
        return ans;
    }
}

